package hu.boltseged.label; import org.springframework.data.jpa.repository.EntityGraph; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface ShipmentLabelRepository extends JpaRepository<ShipmentLabel,UUID>{@EntityGraph(attributePaths={"shipment","shipment.account"}) Optional<ShipmentLabel> findByIdAndShipmentId(UUID id,UUID shipmentId); List<ShipmentLabel> findByShipmentId(UUID shipmentId);}
